('q_prir-5-ryby_24','Kde se vyskytuje sumec?',ARRAY['na souši','ve vzduchu','v polárním moři','v teplých řekách a jezerech']::TEXT[],3,'Sumec žije v teplých vodách.',2,ARRAY[]::TEXT[],NULL,24,'c_prir-5-ryby',NULL,NOW()),
